"""CRUD overlays must participate in startup/view identity and admission."""
import copy,hashlib,json,pathlib,sqlite3,sys,tempfile,unittest
P=pathlib.Path(__file__).resolve().parents[1];sys.path.insert(0,str(P/'tooling'))
import build_catalog,test_round8,test_device_resolution as f,device_resolution as dr,effective_device_inventory as effective,policy_reference
class EffectiveInventory(unittest.TestCase):
 def fixture(self,root):
  inv=test_round8.Review8().fixture(root,'package a; interface I { parcelable P { int x; } void take(in P p); }');build_catalog.build(inv,root/'out');db=sqlite3.connect(root/'out/catalog.sqlite');db.execute('PRAGMA foreign_keys=ON');self.addCleanup(db.close);return db
 def doc(self,db,signature):return json.loads(db.execute('SELECT document_json FROM effective_entries WHERE json_extract(document_json,\'$.canonical_signature\')=?',(signature,)).fetchone()[0])
 def overlay(self,db,doc,state='active',local=False):
  registry=db.execute('SELECT registry_id FROM active_registry').fetchone()[0];key=doc['entry_id'];base=None if local else db.execute('SELECT record_sha256 FROM effective_entries WHERE entry_id=?',(key,)).fetchone()[0];now='2026-10-27T03:00:00Z';db.execute('INSERT INTO overlays VALUES(?,?,?,?,?,?,?,?,?,?)',(key,None if local else key,doc['canonical_signature'],1,None if local else registry,base,state,json.dumps(doc),now,now));db.execute('INSERT INTO entry_history VALUES(?,?,?,?,?,?)',(key,1,'create' if local else 'suppress' if state=='suppressed' else 'update',json.dumps(doc),'fixture',now));db.commit()
 def resolve(self,capture):
  facts=f.facts();facts['platform']={'major':37,'minor':0};return dr.resolve(capture['inventory'],facts,registry_id=capture['registry_id'],catalog_generation=capture['catalog_generation'],overlay_generation=capture['overlay_generation'],capability_epoch=0,view_generation=1)
 def test_suppression_retains_existence_but_denies_known_dispatch(self):
  with tempfile.TemporaryDirectory() as td:
   db=self.fixture(pathlib.Path(td));doc=self.doc(db,'aidl:a.I#take(P)');self.overlay(db,doc,'suppressed');capture=effective.capture(db);snapshot=self.resolve(capture);row=next(r for r in snapshot['entries'] if r['entry_id']==doc['entry_id']);self.assertEqual(row['state'],'available');self.assertEqual(row['catalog_state'],'suppressed');self.assertEqual(capture['base_inventory_count'],len(capture['inventory']));status=dict(snapshot=snapshot,stale=False,generation=1,capability_epoch=0);rule=policy_reference.Rule('allow',row['schema_hash'],frozenset({'platform:local'}),1);entry=policy_reference.Rule('allow','tool',frozenset({'platform:local'}),1)
   self.assertEqual(policy_reference.evaluate_view_fixture([(doc['entry_id'],row['schema_hash'],'platform:local',1)],status,{doc['entry_id']:rule},entry,entry_schema='tool',authority=True),'deny')
 def test_local_addition_is_visible_and_version_unknown(self):
  with tempfile.TemporaryDirectory() as td:
   db=self.fixture(pathlib.Path(td));doc=self.doc(db,'aidl:a.I#take(P)');doc.update(canonical_signature='aidl:a.I#added(int)',name='added',origin='local',overlay_revision=1);doc['entry_id']=hashlib.sha256(doc['canonical_signature'].encode()).hexdigest();doc['arguments']=[{'text':'int','status':'primitive','codec_status':'unknown'}];self.overlay(db,doc,local=True);capture=effective.capture(db);self.assertEqual(len(capture['inventory']),capture['base_inventory_count']+1);row=next(r for r in self.resolve(capture)['entries'] if r['entry_id']==doc['entry_id']);self.assertEqual(row['state'],'unknown');self.assertEqual(row['catalog_state'],'active')
 def test_structured_field_override_changes_transitive_binding_hash(self):
  with tempfile.TemporaryDirectory() as td:
   db=self.fixture(pathlib.Path(td));before=effective.capture(db);binding=self.doc(db,'aidl:a.I#take(P)')['entry_id'];old=next(r for r in self.resolve(before)['entries'] if r['entry_id']==binding);doc=self.doc(db,'aidl:a.I.P#x');doc['return_type']['text']='long';self.overlay(db,doc);after=effective.capture(db);new=next(r for r in self.resolve(after)['entries'] if r['entry_id']==binding);self.assertEqual(new['state'],'available');self.assertNotEqual(old['schema_hash'],new['schema_hash']);self.assertNotEqual(before['inventory_sha256'],after['inventory_sha256']);self.assertEqual(after['overlay_generation'],before['overlay_generation']+1)
 def test_matching_allow_succeeds_but_changed_document_pin_denies(self):
  with tempfile.TemporaryDirectory() as td:
   db=self.fixture(pathlib.Path(td));captured=effective.capture(db);snapshot=self.resolve(captured);doc=self.doc(db,'aidl:a.I#take(P)');key=doc['entry_id'];row=next(r for r in snapshot['entries'] if r['entry_id']==key);status=dict(snapshot=snapshot,stale=False,generation=1,capability_epoch=0);plan=[(key,row['schema_hash'],'platform:local',1)];rule=policy_reference.Rule('allow',row['schema_hash'],frozenset({'platform:local'}),1);entry=policy_reference.Rule('allow','tool',frozenset({'platform:local'}),1)
   self.assertEqual(policy_reference.evaluate_view_fixture(plan,status,{key:rule},entry,entry_schema='tool',authority=True,current_document_hashes=captured['document_hashes']),'admit-candidate');self.assertEqual(policy_reference.evaluate_view_fixture(plan,status,{key:rule},entry,entry_schema='tool',authority=False,current_document_hashes=captured['document_hashes']),'os-unavailable')
   doc['unresolved'].append('New metadata evidence');self.overlay(db,doc);after=effective.capture(db);newrow=next(r for r in self.resolve(after)['entries'] if r['entry_id']==key);self.assertEqual(row['schema_hash'],newrow['schema_hash']);self.assertNotEqual(row['catalog_document_sha256'],newrow['catalog_document_sha256']);self.assertEqual(policy_reference.evaluate_view_fixture(plan,status,{key:rule},entry,entry_schema='tool',authority=True,current_document_hashes=after['document_hashes']),'deny')
 def test_suppressed_type_denies_an_otherwise_allowed_binding(self):
  with tempfile.TemporaryDirectory() as td:
   db=self.fixture(pathlib.Path(td));self.overlay(db,self.doc(db,'aidl:a.I.P'),'suppressed');captured=effective.capture(db);snapshot=self.resolve(captured);key=self.doc(db,'aidl:a.I#take(P)')['entry_id'];row=next(r for r in snapshot['entries'] if r['entry_id']==key);self.assertEqual(row['state'],'available');status=dict(snapshot=snapshot,stale=False,generation=1,capability_epoch=0);rule=policy_reference.Rule('allow',row['schema_hash'],frozenset({'platform:local'}),1);entry=policy_reference.Rule('allow','tool',frozenset({'platform:local'}),1);self.assertEqual(policy_reference.evaluate_view_fixture([(key,row['schema_hash'],'platform:local',1)],status,{key:rule},entry,entry_schema='tool',authority=True,current_document_hashes=captured['document_hashes']),'deny')
if __name__=='__main__':unittest.main()
